CREATE TABLE import_export_task (task_id BIGINT PRIMARY KEY AUTO_INCREMENT,initiated_by_user_id BIGINT NOT NULL,task_type VARCHAR(20) NOT NULL,business_type VARCHAR(30) NOT NULL,task_status VARCHAR(20) NOT NULL DEFAULT 'WAITING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,started_at DATETIME NULL,finished_at DATETIME NULL,result_description VARCHAR(2000) NULL,FOREIGN KEY(initiated_by_user_id) REFERENCES sys_user(user_id),CHECK(task_type IN ('IMPORT','EXPORT')),CHECK(task_status IN ('WAITING','RUNNING','SUCCESS','FAILED','CANCELLED')));
CREATE TABLE import_export_task_file (task_id BIGINT NOT NULL,file_id BIGINT NOT NULL,file_purpose VARCHAR(20) NOT NULL,PRIMARY KEY(task_id,file_id),FOREIGN KEY(task_id) REFERENCES import_export_task(task_id),FOREIGN KEY(file_id) REFERENCES file_resource(file_id));
CREATE TABLE backup_task (task_id BIGINT PRIMARY KEY AUTO_INCREMENT,initiated_by_user_id BIGINT NOT NULL,task_type VARCHAR(20) NOT NULL,task_status VARCHAR(20) NOT NULL DEFAULT 'WAITING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,started_at DATETIME NULL,finished_at DATETIME NULL,result_description VARCHAR(2000),FOREIGN KEY(initiated_by_user_id) REFERENCES sys_user(user_id));
CREATE TABLE backup_task_file (task_id BIGINT NOT NULL,file_id BIGINT NOT NULL,file_purpose VARCHAR(20) NOT NULL,PRIMARY KEY(task_id,file_id),FOREIGN KEY(task_id) REFERENCES backup_task(task_id),FOREIGN KEY(file_id) REFERENCES file_resource(file_id));
INSERT INTO schema_version(version_no) VALUES(4);
